with open(input_path, 'r') as f:
    raw = json.load(f)

data = json.loads(raw['result'])
experiments = data['data']['experiments']

# ==============================
# Extract fields from each experiment
# ==============================
def extract_eval_ppl(exp):
    """Extract eval_ppl from metrics, trying multiple key names."""
    m = exp.get('metrics', {})
    if not m:
        return None
    # Priority: eval_ppl > eval_ppl_holdout > best_eval_ppl
    for key in ['eval_ppl', 'eval_ppl_holdout', 'best_eval_ppl']:
        if key in m and m[key] is not None:
            try:
                return float(m[key])
            except (ValueError, TypeError):
                continue
    return None

def extract_field(exp, field_name):
    """Try to extract a field from metrics, then spec, then spec.hyperparams, then top-level."""
    # Check metrics
    m = exp.get('metrics', {})
    if m and field_name in m:
        return m[field_name]
    # Check spec.hyperparams
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        hp = spec.get('hyperparams', {})
        if isinstance(hp, dict) and field_name in hp:
            return hp[field_name]
        if field_name in spec:
            return spec[field_name]
    # Check top-level
    if field_name in exp:
        return exp[field_name]
    return None

def infer_weighting_method(eid, exp):
    """Infer weighting method from metrics, spec command, or exp_id."""
    # Check metrics
    m = exp.get('metrics', {})
    if m and 'weighting_method' in m:
        return m['weighting_method']
    # Parse from command in spec
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        cmd = spec.get('command', '')
        if '--weighting_method' in cmd:
            match = re.search(r'--weighting_method\s+(\S+)', cmd)
            if match:
                return match.group(1)
    # Infer from exp_id
    if 'uniform' in eid:
        return 'uniform'
    if 'adaptive_fix' in eid or 'adaptive_v2' in eid:
        return 'adaptive'
    if 'adaptive' in eid:
        return 'adaptive'
    if 'ess_only' in eid:
        return 'ess_only'
    if 'grid_b' in eid:
        return 'grid'
    if 'tau_' in eid:
        return 'adaptive'
    if 'contamination_60' in eid:
        return 'adaptive'
    if 'bs8' in eid:
        return 'adaptive'
    if 'detect_remove' in eid:
        return 'detect_remove'
    if 'nmin' in eid:
        return 'adaptive'
    if 'golden_ratio' in eid:
        return 'adaptive'
    if 'detector' in eid or 'datagen' in eid or 'diagnostic' in eid or 'baseline' in eid:
        return 'N/A'
    return 'N/A'

def infer_contamination_ratio(eid, exp):
    val = extract_field(exp, 'contamination_ratio')
    if val is not None:
        return val
    # Parse from command
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        cmd = spec.get('command', '')
        match = re.search(r'--contamination_ratio\s+([\d.]+)', cmd)
        if match:
            return float(match.group(1))
    # Infer from eid
    if 'contamination_60' in eid:
        return 0.6
    if 'contamination_100' in eid or 'contamination100' in eid:
        return 1.0
    return 'N/A'

def infer_tau(eid, exp):
    val = extract_field(exp, 'tau')
    if val is not None:
        return val
    # Parse from command
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        cmd = spec.get('command', '')
        match = re.search(r'--tau\s+([\d.]+)', cmd)
        if match:
            return float(match.group(1))
    # Infer from exp_id
    match = re.search(r'tau_0[._]?(\d+)', eid)
    if match:
        digits = match.group(1)
        # tau_095 -> 0.95, tau_09 -> 0.9, tau_07 -> 0.7, tau_0.6 -> 0.6
        if '.' in eid and 'tau_0.' in eid:
            m2 = re.search(r'tau_(0\.\d+)', eid)
            if m2:
                return float(m2.group(1))
        if len(digits) == 1:
            return float(f"0.{digits}")
        elif len(digits) == 2:
            return float(f"0.{digits}")
        elif len(digits) == 3:
            return float(f"0.{digits}")
    return 'N/A'

def infer_n_min(eid, exp):
    val = extract_field(exp, 'n_min')
    if val is not None:
        return val
    # Parse from command
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        cmd = spec.get('command', '')
        match = re.search(r'--n_min\s+(\d+)', cmd)
        if match:
            return int(match.group(1))
    # Infer from exp_id
    match = re.search(r'nmin(\d+)', eid)
    if match:
        return int(match.group(1))
    return 'N/A'

def infer_batch_size(eid, exp):
    val = extract_field(exp, 'batch_size')
    if val is not None:
        return val
    # Parse from command
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        cmd = spec.get('command', '')
        match = re.search(r'--batch_size\s+(\d+)', cmd)
        if match:
            return int(match.group(1))
    # Infer from exp_id
    match = re.search(r'bs(\d+)', eid)
    if match:
        return int(match.group(1))
    return 'N/A'

def infer_seed(eid, exp):
    val = extract_field(exp, 'seed')
    if val is not None:
        return val
    # Parse from command
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        cmd = spec.get('command', '')
        match = re.search(r'--seed\s+(\d+)', cmd)
        if match:
            return int(match.group(1))
    # Infer from exp_id
    match = re.search(r'seed(\d+)', eid)
    if match:
        return int(match.group(1))
    return 'N/A'

# ==============================
# Build records
