records = []
for eid, exp in experiments.items():
    ppl = extract_eval_ppl(exp)
    record = {
        'exp_id': eid,
        'eval_ppl': round(ppl, 3) if ppl is not None else 'N/A',
        'conclusion': exp.get('conclusion', 'N/A'),
        'weighting_method': infer_weighting_method(eid, exp),
        'contamination_ratio': infer_contamination_ratio(eid, exp),
        'tau': infer_tau(eid, exp),
        'n_min': infer_n_min(eid, exp),
        'batch_size': infer_batch_size(eid, exp),
        'seed': infer_seed(eid, exp),
        'parent': exp.get('parent', extract_field(exp, 'parent') or 'N/A'),
        'hypothesis': exp.get('hypothesis', 'N/A'),
    }
    records.append(record)

# Sort by exp_id for consistency
records.sort(key=lambda r: r['exp_id'])

