# ==============================
# Group logic
# ==============================
def classify(eid):
    if 'uniform_seed' in eid or eid == 'baseline_qwen3_0.6b':
        return 'baseline'
    if 'adaptive_fix_seed' in eid:
        return 'adaptive (n_min=2)'
    if 'adaptive_seed' in eid and 'adaptive_fix' not in eid and 'adaptive_v2' not in eid:
        return 'adaptive (n_min=3)'
    if 'ess_only_seed' in eid:
        return 'ESS-only'
    if eid.startswith('grid_b'):
        return 'grid-sweep'
    if eid.startswith('tau_0'):
        return 'tau-sweep'
    if eid.startswith('contamination_60_'):
        return 'contamination_60'
    if eid.startswith('bs8_'):
        return 'batch_size'
    if eid.startswith('detect_remove_'):
        return 'detect-remove'
    return 'other'

groups = {}
for r in records:
    g = classify(r['exp_id'])
    groups.setdefault(g, []).append(r)

# Define group order
group_order = ['baseline', 'adaptive (n_min=2)', 'adaptive (n_min=3)', 'ESS-only', 
               'grid-sweep', 'tau-sweep', 'contamination_60', 'batch_size', 'detect-remove', 'other']

