# File 2: Markdown
# ==============================
def fmt_ppl(val):
    if val == 'N/A':
        return 'N/A'
    return f"{val:.3f}" if isinstance(val, float) else str(val)

def fmt_conclusion(c):
    if c == 'negative':
        return '⚠️ negative'
    return c

def fmt_val(v):
    if v is None or v == 'N/A':
        return 'N/A'
    return str(v)

lines = []
lines.append("# Provenance Weight Training — Experiment Metrics Summary")
lines.append("")
lines.append(f"**Generated**: 2026-05-16")
lines.append(f"**Total experiments**: {len(records)}")
lines.append("")

# Group counts
lines.append("## Experiment Counts by Group")
lines.append("")
lines.append("| Group | Count |")
lines.append("|-------|-------|")
for g in group_order:
    if g in groups:
        lines.append(f"| {g} | {len(groups[g])} |")
lines.append("")

# Tables per group
for g in group_order:
    if g not in groups:
        continue
    grp = groups[g]
    lines.append(f"## {g}")
    lines.append("")
    lines.append("| exp_id | PPL | conclusion | method | ρ | τ | n_min | bs | seed |")
    lines.append("|--------|-----|-----------|--------|---|---|-------|----|----|")
    # Sort by PPL (N/A last), then by exp_id
    def sort_key(r):
        ppl = r['eval_ppl']
        if ppl == 'N/A':
            return (1, 999, r['exp_id'])
        return (0, float(ppl), r['exp_id'])
    grp.sort(key=sort_key)
    for r in grp:
        ppl_str = fmt_ppl(r['eval_ppl'])
        conc_str = fmt_conclusion(r['conclusion'])
        lines.append(f"| {r['exp_id']} | {ppl_str} | {conc_str} | {fmt_val(r['weighting_method'])} | {fmt_val(r['contamination_ratio'])} | {fmt_val(r['tau'])} | {fmt_val(r['n_min'])} | {fmt_val(r['batch_size'])} | {fmt_val(r['seed'])} |")
    lines.append("")

md_content = "\n".join(lines)
